/// The toxav functions, apart from creating, iterating and killing a ToxAV.
abstract interface class ToxAvApi {
  int iterationInterval();

  int audioIterationInterval();

  void audioIterate();

  int videoIterationInterval();

  void videoIterate();

  void call(FriendNumber friendNumber, int audioBitRate, int videoBitRate);

  void answer(FriendNumber friendNumber, int audioBitRate, int videoBitRate);

  void callControl(FriendNumber friendNumber, CallControl control);

  void audioSendFrame(
    FriendNumber friendNumber,
    Int16List pcm,
    int sampleCount,
    int channels,
    int samplingRate,
  );

  void audioSetBitRate(FriendNumber friendNumber, int bitRate);

  void videoSendFrame(
    FriendNumber friendNumber,
    int width,
    int height,
    Uint8List y,
    Uint8List u,
    Uint8List v,
  );

  void videoSetBitRate(FriendNumber friendNumber, int bitRate);
}

/// [ToxAvApi] through toxav's C functions.
mixin ToxAvFfiApi implements ToxAvApi {
  ToxLibrary get lib;

  Pointer<ToxAV> get pointer;

  @override
  int iterationInterval() {
    return lib.ffi.toxav_iteration_interval(pointer);
  }

  @override
  int audioIterationInterval() {
    return lib.ffi.toxav_audio_iteration_interval(pointer);
  }

  @override
  void audioIterate() {
    lib.ffi.toxav_audio_iterate(pointer);
  }

  @override
  int videoIterationInterval() {
    return lib.ffi.toxav_video_iteration_interval(pointer);
  }

  @override
  void videoIterate() {
    lib.ffi.toxav_video_iterate(pointer);
  }

  @override
  void call(FriendNumber friendNumber, int audioBitRate, int videoBitRate) {
    final a = _Arena(lib);
    try {
      final err = a.error();
      lib.ffi.toxav_call(
        pointer,
        friendNumber.value,
        audioBitRate,
        videoBitRate,
        err,
      );
      _check(err.value, CallError.fromValue, 'toxav_call');
    } finally {
      a.free();
    }
  }

  @override
  void answer(FriendNumber friendNumber, int audioBitRate, int videoBitRate) {
    final a = _Arena(lib);
    try {
      final err = a.error();
      lib.ffi.toxav_answer(
        pointer,
        friendNumber.value,
        audioBitRate,
        videoBitRate,
        err,
      );
      _check(err.value, AnswerError.fromValue, 'toxav_answer');
    } finally {
      a.free();
    }
  }

  @override
  void callControl(FriendNumber friendNumber, CallControl control) {
    final a = _Arena(lib);
    try {
      final err = a.error();
      lib.ffi.toxav_call_control(
        pointer,
        friendNumber.value,
        Toxav_Call_Control.fromValue(control.value),
        err,
      );
      _check(err.value, CallControlError.fromValue, 'toxav_call_control');
    } finally {
      a.free();
    }
  }

  @override
  void audioSendFrame(
    FriendNumber friendNumber,
    Int16List pcm,
    int sampleCount,
    int channels,
    int samplingRate,
  ) {
    if (pcm.length < sampleCount * channels) {
      throw ArgumentError.value(pcm.length, 'pcm', 'too short');
    }
    final a = _Arena(lib);
    try {
      final err = a.error();
      lib.ffi.toxav_audio_send_frame(
        pointer,
        friendNumber.value,
        a.int16s(pcm),
        sampleCount,
        channels,
        samplingRate,
        err,
      );
      _check(err.value, SendFrameError.fromValue, 'toxav_audio_send_frame');
    } finally {
      a.free();
    }
  }

  @override
  void audioSetBitRate(FriendNumber friendNumber, int bitRate) {
    final a = _Arena(lib);
    try {
      final err = a.error();
      lib.ffi.toxav_audio_set_bit_rate(
        pointer,
        friendNumber.value,
        bitRate,
        err,
      );
      _check(err.value, BitRateSetError.fromValue, 'toxav_audio_set_bit_rate');
    } finally {
      a.free();
    }
  }

  @override
  void videoSendFrame(
    FriendNumber friendNumber,
    int width,
    int height,
    Uint8List y,
    Uint8List u,
    Uint8List v,
  ) {
    if (y.length < width * height) {
      throw ArgumentError.value(y.length, 'y', 'too short');
    }
    if (u.length < ((width ~/ 2) * height) ~/ 2) {
      throw ArgumentError.value(u.length, 'u', 'too short');
    }
    if (v.length < ((width ~/ 2) * height) ~/ 2) {
      throw ArgumentError.value(v.length, 'v', 'too short');
    }
    final a = _Arena(lib);
    try {
      final err = a.error();
      lib.ffi.toxav_video_send_frame(
        pointer,
        friendNumber.value,
        width,
        height,
        a.bytes(y),
        a.bytes(u),
        a.bytes(v),
        err,
      );
      _check(err.value, SendFrameError.fromValue, 'toxav_video_send_frame');
    } finally {
      a.free();
    }
  }

  @override
  void videoSetBitRate(FriendNumber friendNumber, int bitRate) {
    final a = _Arena(lib);
    try {
      final err = a.error();
      lib.ffi.toxav_video_set_bit_rate(
        pointer,
        friendNumber.value,
        bitRate,
        err,
      );
      _check(err.value, BitRateSetError.fromValue, 'toxav_video_set_bit_rate');
    } finally {
      a.free();
    }
  }
}

void _check<T extends Enum>(
  int error,
  T Function(int) toError,
  String function,
) {
  if (error != 0) {
    throw ApiException(toError(error), function);
  }
}

Uint8List _read(Pointer<Uint8> data, int length) =>
    Uint8List.fromList(data.asTypedList(length));

/// Native memory for one call, freed together afterwards.
final class _Arena {
  final ToxLibrary _lib;
  final _pointers = <Pointer<NativeType>>[];

  _Arena(this._lib);

  Pointer<T> _add<T extends NativeType>(Pointer<T> pointer) {
    _pointers.add(pointer);
    return pointer;
  }

  Pointer<CEnum> error() => _add(_lib.allocator<CEnum>());

  Pointer<Uint8> buffer(int length) =>
      _add(_lib.allocator<Uint8>(length == 0 ? 1 : length));

  Pointer<Uint32> ids(int length) =>
      _add(_lib.allocator<Uint32>(length == 0 ? 1 : length));

  Pointer<Uint8> bytes(List<int> data) {
    final pointer = buffer(data.length);
    pointer.asTypedList(data.length).setAll(0, data);
    return pointer;
  }

  Pointer<Int16> int16s(List<int> data) {
    final pointer = _add(_lib.allocator<Int16>(data.isEmpty ? 1 : data.length));
    pointer.asTypedList(data.length).setAll(0, data);
    return pointer;
  }

  Pointer<CChar> string(String value) =>
      bytes(utf8.encode('$value\u0000')).cast();

  void free() => _pointers.forEach(_lib.allocator.free);
}
